# rolesviews_data.py
import io, base64

# ⚠️ Substitui o conteúdo do _ROLESVIEWS_B64 pela tua string Base64
_ROLESVIEWS_B64 = """

""".strip()

def get_rolesviews_bytesio() -> io.BytesIO:
    """
    Devolve um BytesIO com o conteúdo do Excel RolesViews.xlsx embutido.
    """
    raw = base64.b64decode(_ROLESVIEWS_B64)
    bio = io.BytesIO(raw)
    bio.seek(0)
    return bio
